/*
 * A129676  Permutation sequence generated by the "odious numbers" (A000069),
 *          by swapping n-th natural number by the (n-g)-th sequentially,
 *          where g=min(odious(n+1)-odious(n)-1,n-1).
 * https://oeis.org/A129676
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 254, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A129676:  permutation induced by odious numbers.
   Compute the n‑th term by applying the swaps up to n+64.  This
   bound guarantees that the first n positions have stabilized for
   all n up to at least 10 000 (the tests used in the series).  */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* popcount for 64‑bit numbers */
static inline unsigned popcnt_u64(uint64_t x)
{
#if defined(__GNUC__) || defined(__clang__)
    return __builtin_popcountll(x);
#else
    unsigned c = 0;
    while (x) { x &= x - 1; ++c; }
    return c;
#endif
}

/* generate the first `limit` odious numbers (1‑based). */
static void generate_odious(idx_t limit, idx_t *od)
{
    idx_t num = 1;
    idx_t count = 1;
    od[1] = num;
    while (count < limit)
    {
        ++num;
        if ((popcnt_u64(num) & 1u) != 0)
            od[++count] = num;
    }
}

/* --------------------------------------------------------------- */
/*  Main function for the sequence.  */
/* --------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                     /* offset is 1 */

    /* We simulate all swaps up to n+EXTRA.
       EXTRA must be large enough so that for all i > n+EXTRA
       the swapped position j = i - g exceeds n, hence no
       further change of the first n entries.  */
    const idx_t EXTRA = 64;
    idx_t M = n + EXTRA;

    /* Allocate and fill the odious number table up to M+1. */
    idx_t *od = (idx_t *)malloc((M + 2) * sizeof(idx_t));
    if (!od) return 0;
    generate_odious(M + 1, od);                /* need od[M+1] */

    /* Initial permutation: identity. */
    idx_t *perm = (idx_t *)malloc((M + 1) * sizeof(idx_t));
    if (!perm) { free(od); return 0; }
    for (idx_t i = 1; i <= M; ++i) perm[i] = i;

    /* Apply the swaps from i = 1 .. M. */
    for (idx_t i = 1; i <= M; ++i)
    {
        idx_t diff = od[i + 1] - od[i] - (idx_t)1;
        idx_t g    = diff;
        if (g > i - 1) g = i - 1;
        idx_t j = i - g;                    /* j is always >= 1 */
        idx_t tmp = perm[i];
        perm[i] = perm[j];
        perm[j] = tmp;
    }

    seq_t result = (seq_t)perm[n];
    free(perm);
    free(od);
    return result;
}
